// static int r_ending(struct SN_env * z)
unsafe extern "C" fn r_ending(z: *mut SN_env) -> c_int {
    (*z).ket = (*z).c;
    if find_among_b(z, a_3.as_ptr(), 57) == 0 {
        return 0;
    }
    (*z).bra = (*z).c;
    {
        let ret = r_R2(z);
        if ret <= 0 {
            return ret;
        }
    }
    {
        let ret = slice_del(z);
        if ret < 0 {
            return ret;
        }
    }
    1
}

// extern int armenian_UTF_8_stem(struct SN_env * z)
#[no_mangle]
pub unsafe extern "C" fn armenian_UTF_8_stem(z: *mut SN_env) -> c_int {
    {
        let ret = r_mark_regions(z);
        if ret < 0 {
            return ret;
        }
    }
    (*z).lb = (*z).c;
    (*z).c = (*z).l;

    {
        let mlimit1: c_int;
        if (*z).c < *(*z).I.offset(1) {
            return 0;
        }
        mlimit1 = (*z).lb;
        (*z).lb = *(*z).I.offset(1);
        {
            let m2 = (*z).l - (*z).c;
            let _ = m2;
            {
                let ret = r_ending(z);
                if ret < 0 {
                    return ret;
                }
            }
            (*z).c = (*z).l - m2;
        }
        {
            let m3 = (*z).l - (*z).c;
            let _ = m3;
            {
                let ret = r_verb(z);
                if ret < 0 {
                    return ret;
                }
            }
            (*z).c = (*z).l - m3;
        }
        {
            let m4 = (*z).l - (*z).c;
            let _ = m4;
            {
                let ret = r_adjective(z);
                if ret < 0 {
                    return ret;
                }
            }
            (*z).c = (*z).l - m4;
        }
        {
            let m5 = (*z).l - (*z).c;
            let _ = m5;
            {
                let ret = r_noun(z);
                if ret < 0 {
                    return ret;
                }
            }
            (*z).c = (*z).l - m5;
        }
        (*z).lb = mlimit1;
    }
    (*z).c = (*z).lb;
    1
}

// extern struct SN_env * armenian_UTF_8_create_env(void)
#[no_mangle]
pub unsafe extern "C" fn armenian_UTF_8_create_env() -> *mut SN_env {
    SN_create_env(0, 2)
}

// extern void armenian_UTF_8_close_env(struct SN_env * z)
#[no_mangle]
pub unsafe extern "C" fn armenian_UTF_8_close_env(z: *mut SN_env) {
    SN_close_env(z, 0)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::snowball::api::SN_set_current;

    unsafe fn stem_word(w: &[u8]) -> Vec<u8> {
        let z = armenian_UTF_8_create_env();
        SN_set_current(z, w.len() as c_int, w.as_ptr());
        let r = armenian_UTF_8_stem(z);
        assert!(r >= 0);
        let out = std::slice::from_raw_parts((*z).p, SIZE((*z).p) as usize).to_vec();
        armenian_UTF_8_close_env(z);
        out
    }

    // Real Armenian words (Armenian script, UTF-8).
    // grqi = of book, books, etc. Use a small set of inflected words.
    const W_GIRQ: &[u8] = &[0xD5, 0xA3, 0xD5, 0xAB, 0xD6, 0x80, 0xD6, 0x84]; // book
    const W_DProyc: &[u8] =
        &[0xD5, 0xA4, 0xD5, 0xBA, 0xD6, 0x80, 0xD5, 0xB8, 0xD6, 0x81]; // school-ish
    const W_MARD: &[u8] = &[0xD5, 0xB4, 0xD5, 0xA1, 0xD6, 0x80, 0xD5, 0xA4]; // man

    #[test]
    fn nonempty_and_nonneg() {
        unsafe {
            for w in [W_GIRQ, W_DProyc, W_MARD] {
                let out = stem_word(w);
                assert!(!out.is_empty());
            }
        }
    }

    #[test]
    fn idempotence() {
        unsafe {
            // A short root word that is below R1 should be left UNCHANGED.
            // W_GIRQ has no R1 region long enough to strip, so should be stable.
            for w in [W_GIRQ, W_DProyc, W_MARD] {
                let once = stem_word(w);
                let twice = stem_word(&once);
                assert_eq!(once, twice, "stem(stem(w)) != stem(w)");
            }
        }
    }

    #[test]
    fn short_root_unchanged() {
        unsafe {
            // Two-letter Armenian root, no suffix to remove (below R1).
            let root: &[u8] = &[0xD5, 0xB4, 0xD5, 0xA1]; // "ma"
            let out = stem_word(root);
            assert_eq!(out, root.to_vec());
        }
    }
}
